"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["96922"],{43273(e){e.exports=JSON.parse('{"id":"V4-150","slug":"carbon-tax","term":"Carbon Tax","also_known_as":[],"difficulty":"Intermediate","definition":"A carbon tax is a tax charged on greenhouse gas emissions or on fossil fuels according to their carbon content, designed to make polluters pay for the climate damage they cause and encourage lower emissions.","explanation":["A carbon tax puts a direct price on carbon. Because it raises the cost of fossil fuels and other high-carbon activities, it encourages businesses and households to use less energy, switch to cleaner alternatives and invest in low-carbon technology.","Finland introduced the world\u2019s first carbon tax in 1990, and Sweden followed in 1991. Sweden\u2019s carbon tax is among the highest in the world. Canada introduced a national carbon pricing system, although the consumer fuel charge was ended in 2025, while pricing for large industrial emitters continued.","For example, a carbon tax of 50 per tonne of carbon dioxide would add a cost to every litre of petrol or unit of gas burned, based on the emissions it produces.","Economists often favour carbon taxes because they reduce emissions where it is cheapest to do so and raise revenue that can be used to cut other taxes or support households. A carbon tax gives price certainty, but the amount of emissions reduction is uncertain, unlike a cap in an emissions trading system. Carbon taxes can be politically unpopular, especially if they raise energy costs for lower-income households."],"note":"","total":1725,"prev":{"slug":"carbon-offset","term":"Carbon Offset"},"next":{"slug":"card-network","term":"Card Network"}}')}}]);